      policies=["SEC-EXEC-001", "SEC-LANG-001", "SEC-DB-001"],
      refs=[s("SRC-FSHARP-ANALYZERS", rel="informed-by"), s("SRC-ROSLYN-SECURITY", rel="informed-by")],
